WFJ.Data.add("gossip", {
  ["6c0d7199efc8fb26"] = { "Myolor, un tempo forgiavo armature e ora vorrei invece imparare la via del Fabbro d'Armi. Mi insegnerai?", "." },
  ["6c0e50032849c1d3"] = { "Non ho più niente da insegnarti! Non a qualcuno che ne sa quanto te, almeno! Voi tipi dell'⟦Horde=Orda⟧ dovete parlare con Nogg a Orgrimmar!", "." },
  ["6c1285a421d5735e"] = { "Il generale Rajaxx è stato asfaltato. Un'altra vittoria per Andorov.", "." },
  ["6c154e0fabd15b30"] = { "Mi occupo del reclutamento per il ⟦Frostwolf Clan=Clan Lupi Bianchi⟧. Come soldato dei Lupi Bianchi, è tua responsabilità presentarti da me man mano che il tuo grado nel clan sale.\n\nOnore e rispetto si guadagnano su questo campo gelido.", "." },
  ["6c186150f1763eb6"] = { "Ah, ben ritrovat<o/a>, {name}.", "." },
  ["6c2180cb30139186"] = { "%s rigurgita una disgustosa ⟦Bile Sludge=Poltiglia di Bile⟧!", "." },
  ["6c26d1ff9d2e5cc4"] = { "I Cristalli Ash'ari sono stati distrutti! Lo Slaughterhouse è vulnerabile!", "." },
  ["6c27985e8c5b2c56"] = { "Maestro di gilda", "." },
  ["6c2b18257a535d90"] = { "Voi bipedi non siete niente! I miei figli potrebbero battervi!", "." },
  ["6c2c057b34db4019"] = { "La Stormpike Aid Station è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ la conquisterà!", "." },
  ["6c2c5e5942abc9c8"] = { "Sai, ho sempre sognato di entrare tra i Prospettori, ma ho la testa per i numeri fin dalla nascita e la Gilda ha deciso che il mio posto era a tenere i conti! Studiare, studiare, ogni giorno della mia giovinezza...", "." },
  ["6c3484b8f43b30c9"] = { "Le vostre vecchie vite, i vostri desideri mortali non significano nulla... ora siete accoliti del padrone, e servirete la causa senza fare domande! La gloria più grande è morire al servizio del padrone!", "." },
  ["6c394d04a02937fe"] = { "La bestia è morta! Tutto bene a ⟦Darkshire=Borgoscuro⟧!", "." },
  ["6c435291354292e2"] = { "È vero, giovane {race}: noi e l'⟦Alliance=Alleanza⟧ abbiamo raccolto e preparato tutto ciò che ci servirà per l'imminente conflitto ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Proprio ora tutto questo viene spedito alla ⟦Cenarion Hold=Fortezza Cenariana⟧, e dovrebbe arrivare entro $2113w giorni. Quando tutto sarà a posto, qualcuno dovrà suonare il gong sullo Scarab Dais per aprire le porte e dare inizio alla guerra.", "." },
  ["6c4c6418dafc1636"] = { "Il nostro padrone ti vuole!", "." },
  ["6c5cf3ed922de201"] = { "Stolto impudente! Ti ucciderò con le mie mani!", "." },
  ["6c6080e15ecf5982"] = { "Salute, viandante, hai la mia eterna gratitudine per averci liberato da quelle orribili creature! Cominciavo a pensare di dovermi nascondere per sempre!", "." },
  ["6c6128e15a0d0edf"] = { "Grazie per gli elmi, {name}. Ridurranno davvero le nostre spese mediche...", "." },
  ["6c62f3e7c7c2c854"] = { "Rapido e sicuro. Taglia un tendine qui, recidi un'arteria là. Posso mostrarti come trasformare qualsiasi coltello in un perfetto strumento di morte.", "." },
  ["6c6447f489af9b94"] = { "%s legge l'antico testo che {name} gli ha portato...", "." },
  ["6c645a0098b676be"] = { "Il cuore di un traditore è un reagente potente. Le fiamme accetteranno avidamente un'offerta simile e arderanno più intense mentre lo consumano.", "." },
  ["6c6eea75570e4c08"] = { "%s saluta tutti con la mano.", "." },
  ["6c7093dc099ced94"] = { "Hai l'amicizia degli Zandalari! Ti sei <spinto/spinta> nel profondo della tana del Dio del Sangue, {class}. Farai bene ad ascoltare ciò che ho da dirti.\n\nMolte migliaia di anni fa, mentre i troll indigeni dell'impero di Zul'Aman combattevano gli invasori alti elfi, quegli infedeli, una grande magia fu rubata a Zanza. Gli alti elfi usarono questa magia per incantare le loro armi e armature, così da sottomettere i troll della regione.", "." },
  ["6c76459a1bc81c7e"] = { "%s barcolla all'indietro mentre la freccia gli si conficca a fondo nel petto.", "." },
  ["6c7b7e9a9fca7758"] = { "Il ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧ si trova lungo il lato della strada, poco a nord del ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧.\n\nNon è controllato da nessuna delle due parti.", "." },
  ["6c7f0d86124b4a13"] = { "Dov'è l'istruttore di ⟦First Aid=Primo Soccorso⟧?", "." },
  ["6c82f465ac73fea5"] = { "Impari in fretta, <ragazzo/ragazza>, molto più in fretta di quanto riesca a starti dietro. Se vuoi continuare l'addestramento, ti consiglio di andare dal mio maestro. Si chiama Rotgath, ⟦Rotgath Stonebeard=Rotgath Barbapietra⟧, e lo trovi a ⟦Ironforge=Forgiardente⟧, nella ⟦Great Forge=Grande Forgia⟧.", "." },
  ["6c8a8f84282a97f3"] = { "Sei tornat<o/a>! Sorprendente, {race}. Hai scoperto il vero nome?", "." },
  ["6c8feeed64a0438a"] = { "E ora sai perché vivo in un cratere.", "." },
  ["6c9159fd51313f82"] = { "Il Fruit of Fertility?", "." },
  ["6c9825cd6ca5d0cf"] = { "È un segreto per tutti... anche per me!\n\nSono felice che tu sia <riuscito/riuscita> a scovarmi: per fortuna non mi nascondo in un cespuglio o sotto una roccia, vero?", "." },
  ["6ca052c8fbe43a0a"] = { "Prendete posto, gente! La gara comincia tra 2 minuti!", "." },
  ["6cab0f262b9f2e86"] = { "Ha tutta l'aria di essere una di quelle giornate.", "." },
  ["6cb08c8055ff0e78"] = { "La cassetta di sicurezza dell'⟦SI:7=IR:7⟧ comincia a vibrare e ronzare. Da nord si sente provenire un forte fruscio.", "." },
  ["6cb0b210a88bdb67"] = { "In quegli anni, quando la discordia riempiva la terra mentre la Legione e il Flagello saccheggiavano le nostre case e uccidevano le nostre famiglie, questi insetti vivevano sotto di noi. Sotto le nostre case, in attesa.", "." },
  ["6cb3fcc2a636c973"] = { "Oh, fratelli miei! Che possiate trovare riposo nelle vostre tombe d'acqua!", "." },
  ["6cc03ae132e34fd8"] = { "Hai rinchiuso il maresciallo sbagliato, {name}. Preparati a essere distrutto!", "." },
  ["6ccdf7677a002dc6"] = { "{name} sta arrivando in fretta! È l'ora della vendetta!", "." },
  ["6cce612ca887c8f8"] = { "Volentieri, signore.", "." },
  ["6ccf90b161b96401"] = { "{name} sta arrivando in fretta! Alle armi!", "." },
  ["6cd0e4ba00141c83"] = { "La prima armatura dell'Ardore fu forgiata esclusivamente per il gran signore scarlatto Mograine. Quando la indossava per intero, il gran signore sembrava un demone uscito dalle profondità del Nether.\n\nSì, era proprio uno spettacolo vedere Mograine gettarsi in mezzo a cento soldati del Flagello, con il Brandicenere levato in alto, e uscirne dall'altra parte in una nube di polvere e fiamme, con i nemici ridotti in cenere sotto i suoi piedi.", "." },
  ["6cd7bc510e871dbd"] = { "Le Segrete di ⟦Stormwind=Roccavento⟧ sono un complesso carcerario di massima sicurezza, nascosto sotto il distretto dei canali della città di ⟦Stormwind=Roccavento⟧. Sorvegliate dal custode Cuorsaldo, le Segrete ospitano piccoli criminali, ribelli politici, assassini e una ventina dei criminali più pericolosi del paese. Di recente una rivolta guidata dai prigionieri ha gettato le Segrete nel caos: le guardie sono state cacciate e i detenuti si aggirano liberi.", "." },
  ["6cda9d6033a3bcb5"] = { "Perché tu e Rocknot non andate a cercarvi un posticino appartato...", "." },
})
